exec('import csv,os,requests\ndecisions=list(csv.DictReader(open("intraday_decisions.csv",encoding="utf-8"))) if os.path.exists("intraday_decisions.csv") else []\nstate_file="intraday_alert_state.csv"; old=list(csv.DictReader(open(state_file,encoding="utf-8"))) if os.path.exists(state_file) else []; notified={(r["ticker"],r["signal_date"],r["session_date"]):r["decision"] for r in old}; events=[]\nfor r in decisions:\n key=(r["ticker"],r["signal_date"],r["session_date"]); current=r["decision"]; previous=notified.get(key)\n if current in ("ACHAT CONFIRME","ACHAT REACTIVE","SETUP INITIAL INVALIDE","EXPIRE") and current!=previous: events.append(r); notified[key]=current\nfor r in events:\n icon="✅" if r["decision"]=="ACHAT CONFIRME" else "🔄" if r["decision"]=="ACHAT REACTIVE" else "⚠️" if r["decision"]=="SETUP INITIAL INVALIDE" else "⌛"; devise="EUR" if r["ticker"].endswith((".PA",".AS")) else "USD"; text="<b>"+icon+" "+r["decision"]+"</b>\\n\\n<b>"+r["ticker"]+"</b>\\nDate : "+r["session_date"]+"\\nHeure : "+r["decision_time"]+"\\nPrix décision : "+r["decision_close"]+" "+devise+"\\nVWAP : "+r["vwap"]+"\\nOR haut : "+r["opening_range_high"]+" | OR bas : "+r["opening_range_low"]+"\\nVolume : "+r["decision_volume"]+"\\n\\nMotif : "+r["reason"]+"\\nÉtat suivant : "+r["next_state"]+"\\n\\n<i>Paper trading uniquement.</i>"; response=requests.post("https://api.telegram.org/bot"+os.environ["TELEGRAM_BOT_TOKEN"]+"/sendMessage",data={"chat_id":os.environ["TELEGRAM_CHAT_ID"],"text":text,"parse_mode":"HTML"},timeout=30); print(r["ticker"],r["decision"],response.status_code,response.json().get("ok"))\nwith open(state_file,"w",newline="",encoding="utf-8") as q:\n fields=["ticker","signal_date","session_date","decision"]; w=csv.DictWriter(q,fieldnames=fields); w.writeheader(); w.writerows({"ticker":k[0],"signal_date":k[1],"session_date":k[2],"decision":v} for k,v in notified.items())\nprint("Alertes envoyées :",len(events))')
